using System.Text;
using System.Text.Json.Nodes;

namespace JarvisCode.App.Services;

/// <summary>
/// /plugin-types — writes jarvis-code-mcp.d.ts: TypeScript input types for the
/// connected MCP tools, generated from their JSON schemas, for typing a plugin
/// against this session (the reference's /plugin-types).
/// </summary>
public static class McpTypings
{
    public const string FileName = "jarvis-code-mcp.d.ts";

    /// <summary>Renders the declaration file for (toolName, inputSchema) pairs.</summary>
    public static string Generate(IEnumerable<(string Name, JsonObject Schema)> tools)
    {
        var text = new StringBuilder(
            "// Generated by /plugin-types — input types of the MCP tools connected to this session.\n" +
            "// Regenerate after adding or removing MCP servers.\n\n" +
            "declare namespace JarvisCodeMcp {\n");
        bool any = false;
        foreach (var (name, schema) in tools.OrderBy(t => t.Name, StringComparer.Ordinal))
        {
            any = true;
            text.Append("  /** Input of the `").Append(name).Append("` tool. */\n");
            text.Append("  interface ").Append(InterfaceName(name)).Append(' ');
            WriteObject(text, schema, indent: 2);
            text.Append("\n\n");
        }

        if (!any)
        {
            text.Append("  // No MCP tools are connected.\n");
        }

        text.Append("}\n");
        return text.ToString();
    }

    /// <summary>mcp__server__tool-name → McpServerToolName.</summary>
    internal static string InterfaceName(string toolName)
    {
        var parts = toolName.Split(['_', '-', '.'], StringSplitOptions.RemoveEmptyEntries);
        var name = new StringBuilder();
        foreach (var part in parts)
        {
            name.Append(char.ToUpperInvariant(part[0])).Append(part.AsSpan(1));
        }

        return name.Length > 0 ? name.ToString() : "Tool";
    }

    private static void WriteObject(StringBuilder text, JsonObject schema, int indent)
    {
        var properties = schema["properties"] as JsonObject;
        if (properties is null || properties.Count == 0)
        {
            text.Append("{ [key: string]: unknown }");
            return;
        }

        var required = new HashSet<string>(StringComparer.Ordinal);
        if (schema["required"] is JsonArray requiredArray)
        {
            foreach (var item in requiredArray)
            {
                if (item?.GetValue<string>() is { } key)
                {
                    required.Add(key);
                }
            }
        }

        text.Append("{\n");
        var pad = new string(' ', indent + 2);
        foreach (var (key, value) in properties)
        {
            if (value is not JsonObject property)
            {
                continue;
            }

            if (property["description"]?.GetValue<string>() is { Length: > 0 } description)
            {
                text.Append(pad).Append("/** ").Append(description.Replace("*/", "*\\/").ReplaceLineEndings(" ")).Append(" */\n");
            }

            text.Append(pad).Append(Quote(key)).Append(required.Contains(key) ? ": " : "?: ");
            WriteType(text, property, indent + 2);
            text.Append(";\n");
        }

        text.Append(new string(' ', indent)).Append('}');
    }

    private static void WriteType(StringBuilder text, JsonObject schema, int indent)
    {
        if (schema["enum"] is JsonArray options && options.Count > 0)
        {
            text.Append(string.Join(" | ", options.Select(o => o switch
            {
                null => "null",
                JsonValue v when v.TryGetValue<string>(out var s) => $"\"{s.Replace("\"", "\\\"")}\"",
                _ => o.ToJsonString(),
            })));
            return;
        }

        var type = schema["type"] switch
        {
            JsonValue v when v.TryGetValue<string>(out var s) => s,
            JsonArray a when a.Count > 0 && a[0]?.GetValue<string>() is { } first => first,
            _ => null,
        };
        switch (type)
        {
            case "string":
                text.Append("string");
                break;
            case "number" or "integer":
                text.Append("number");
                break;
            case "boolean":
                text.Append("boolean");
                break;
            case "null":
                text.Append("null");
                break;
            case "array":
                if (schema["items"] is JsonObject items)
                {
                    WriteType(text, items, indent);
                    text.Append("[]");
                }
                else
                {
                    text.Append("unknown[]");
                }

                break;
            case "object":
                WriteObject(text, schema, indent);
                break;
            default:
                text.Append("unknown");
                break;
        }
    }

    private static string Quote(string key) =>
        key.Length > 0 && (char.IsLetter(key[0]) || key[0] == '_') && key.All(c => char.IsLetterOrDigit(c) || c == '_')
            ? key
            : $"\"{key.Replace("\"", "\\\"")}\"";
}
